//! Independent18-profile captured-pair, timing, membership and reward matrix.
use gielinor_world::{assembly::{Recipe,PreciseRecipe},held_use::{Handler,Scope,Type,Request},inventory::{Inventory,Item},simulation::{World,PlayerData,WorldEvent},stats::Stats,npc::RandomSource,CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("deterministic pair assembly drew RNG")}}
fn profile(i:usize)->PreciseRecipe{let(raw,out,level,xp,member,first,seq,spot)=if i<11{let(raw,out)=[(1673,1692),(1675,1694),(1677,1696),(1679,1698),(1681,1700),(1683,1702),(6579,6581),(19501,19541),(21099,21108),(21102,21111),(21105,21114)][i];(raw,out,1,40,i>=5,1759,None,None)}else if i<14{let(raw,out,level,member)=[(1714,1716,1,false),(1720,1722,1,true),(10134,10132,37,true)][i-11];(raw,out,level,40,member,1759,None,None)}else{let(raw,out,level,xp,spot)=[(571,1395,54,1000,1370),(575,1399,58,1125,1371),(569,1393,62,1250,1372),(573,1397,66,1375,306)][i-14];(raw,out,level,xp,true,1391,Some(7531),Some(spot))};PreciseRecipe{recipe:Recipe{first,second:raw,output:out,skill:12,level,base_xp:if i<14{4}else{0},members:member},xp_tenths:xp,ticks:if i<14{1}else{3},animation:seq,spot}}
fn credit(inv:&mut Inventory,first:usize,second:usize,out:i32){inv.restore_slot(first,None).unwrap();inv.restore_slot(second,None).unwrap();let free=(0..28).find(|&s|inv.get(s).is_none()).unwrap();inv.restore_slot(free,Some(Item{id:out,count:1,vars:0})).unwrap();}
fn fixture(r:PreciseRecipe,reverse:bool)->(World,gielinor_world::simulation::ActorId,gielinor_world::assembly_production::Request){let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent pair late policy".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:if s==27{995}else{1931},count:if s==27{1000}else{1},vars:0})).unwrap();}for s in 0..14{d.inventory.restore_slot(s,Some(Item{id:r.recipe.first,count:1,vars:0})).unwrap();}for s in 14..28{d.inventory.restore_slot(s,Some(Item{id:r.recipe.second,count:1,vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[r.recipe.first,r.recipe.second]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,r.recipe.first,r.recipe.second,Handler::AssemblyProduction{recipe:r,cycle_ticks:2}).unwrap();let h=if reverse{Request{selected_slot:27,selected_id:r.recipe.second,target_slot:13,target_id:r.recipe.first}}else{Request{selected_slot:13,selected_id:r.recipe.first,target_slot:27,target_id:r.recipe.second}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let q=w.take_assembly_production_request(a).unwrap().unwrap();w.drain_events();(w,a,q)}
#[test]fn two_hundred_eighty_remaining_full_bag_count_caps(){let mut cases=0;for i in 13..18{let r=profile(i);for reverse in[false,true]{for count in 1..=28{let(mut w,a,q)=fixture(r,reverse);let before=w.data(a).unwrap().clone();let mut expected=before.inventory.clone();let mut stats=before.stats.clone();let wanted=count.min(14) as usize;let mut made=0;w.start_assembly_production(a,q,0,count).unwrap();for _ in 0..(r.ticks as usize+2*wanted+10){w.tick_with_random(&mut NoDraw).unwrap();let n=w.drain_events().iter().filter(|e|matches!(e,WorldEvent::AssemblyMade{..})).count();assert!(n<=1);if n==1{assert!(made<wanted);let first=if made==0{13}else{made-1};credit(&mut expected,first,first+14,r.recipe.output);made+=1;stats.set_fine_xp(12,before.stats.fine_xp(12)+made as i32*(i32::from(r.xp_tenths)*125/100)).unwrap();}assert_eq!(w.data(a).unwrap().inventory,expected,"profile{i} reverse{reverse} requested{count} made{made}");assert_eq!(w.data(a).unwrap().stats,stats);}assert_eq!(made,wanted);cases+=1;}}println!("PG_PAIR_COUNTS profile={i} cumulative_cases={cases}");}assert_eq!(cases,280);}
